// MARK: - Errors

/// Error enum for ElementalInference
public struct ElementalInferenceErrorType: AWSErrorType {
    enum Code: String {
        case accessDeniedException = "AccessDeniedException"
        case conflictException = "ConflictException"
        case internalServerErrorException = "InternalServerErrorException"
        case resourceNotFoundException = "ResourceNotFoundException"
        case serviceQuotaExceededException = "ServiceQuotaExceededException"
        case tooManyRequestException = "TooManyRequestException"
        case validationException = "ValidationException"
    }

    private let error: Code
    public let context: AWSErrorContext?

    /// initialize ElementalInference
    public init?(errorCode: String, context: AWSErrorContext) {
        guard let error = Code(rawValue: errorCode) else { return nil }
        self.error = error
        self.context = context
    }

    internal init(_ error: Code) {
        self.error = error
        self.context = nil
    }

    /// return error code string
    public var errorCode: String { self.error.rawValue }

    /// You do not have sufficient access to perform this action.
    public static var accessDeniedException: Self { .init(.accessDeniedException) }
    /// The request could not be completed due to a conflict.
    public static var conflictException: Self { .init(.conflictException) }
    /// An internal server error occurred. This is a temporary condition and the request can be retried. If the problem persists, contact AWS Support.
    public static var internalServerErrorException: Self { .init(.internalServerErrorException) }
    /// The resource specified in the action doesn't exist.
    public static var resourceNotFoundException: Self { .init(.resourceNotFoundException) }
    /// The request was rejected because it would exceed one or more service quotas for your account. Review your service quotas and either delete unused resources or request a quota increase.
    public static var serviceQuotaExceededException: Self { .init(.serviceQuotaExceededException) }
    /// The request was denied due to request throttling. Too many requests have been made within a given time period. Reduce the frequency of requests and use exponential backoff when retrying.
    public static var tooManyRequestException: Self { .init(.tooManyRequestException) }
    /// The input fails to satisfy the constraints specified by the service. Check the error message for details about which parameter or field is invalid and correct the request before retrying.
    public static var validationException: Self { .init(.validationException) }
}

extension ElementalInferenceErrorType: Equatable {
    public static func == (lhs: ElementalInferenceErrorType, rhs: ElementalInferenceErrorType) -> Bool {
        lhs.error == rhs.error
    }
}

extension ElementalInferenceErrorType: CustomStringConvertible {
    public var description: String {
        return "\(self.error.rawValue): \(self.message ?? "")"
    }
}
